files.content:
.root {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  margin: 0;
  font-family: Helvetica, Arial, sans-serif;
  font-size: 14px;
  background: #f2f2f2;
}

.root__container {
  column-gap: 30px;
  row-gap: 30px;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  max-width: 980px;
}

.card {
  display: flex;
  flex-direction: column;
  border-radius: 2px;
  box-shadow: -1px 2px 4px rgb(0 0 0 / 0.25), 1px 1px 3px rgb(0 0 0 / 0.1);
  background-color: #fff;
}

.card__image {
  width: 100%;
  height: 100%;
  max-height: 170px;
  object-fit: cover;
}

.card__title {
  margin-bottom: 10px;
  font-size: 24px;
}

.card__link {
  display: inline-block;
  border-radius: 2px;
  padding: 10px;
  color: black;
  text-decoration: none;
}

.card__wrap {
  flex-grow: 1;
  padding: 0 10px 15px;
}

.card__link:hover {
  background-color: rgb(255 219 77);
}
